theorem setIntegral_laurentPairing (s : Finset ℤ) (c d : ℤ → ℂ) {a b : ℝ}
    (ha : 0 < a) (hab : a ≤ b) :
    (∫ w in deningerAnnulus a b, laurentPairing s c d w)
      = ∑ k ∈ s, c k * (starRingEnd ℂ) (d k)
          * (if k = 0 then (2 * π * Real.log (b / a) : ℂ)
             else 2 * π * ((b ^ (2 * k) - a ^ (2 * k)) / (2 * k)))

